    def get_imports_per_hour():
        """Returns the number imports happened in past one hour duration."""
        try:
            result = db.query(
                "SELECT count(*) as count FROM import_item"
                " WHERE import_time > CURRENT_TIMESTAMP - interval '1' hour"
